-- Catálogos, seeds y rol de la aplicación.
SELECT pg_temp.verificar((SELECT count(*) FROM roles) = 7, 'roles: 7 filas');
SELECT pg_temp.verificar((SELECT count(*) FROM areas) = 6, 'áreas: 6 filas');
SELECT pg_temp.verificar((SELECT count(*) FROM tipos_atencion) = 5, 'tipos de atención: 5 filas');
SELECT pg_temp.verificar((SELECT count(*) FROM tipos_atencion WHERE es_emergencia) = 1, 'solo un tipo de atención es emergencia');
SELECT pg_temp.verificar((SELECT count(*) FROM comunidades_linguisticas) = 26, 'comunidades lingüísticas: 22 mayas, xinka, garífuna, castellano y "No indica"');
SELECT pg_temp.verificar((SELECT nombre_comunidad_linguistica FROM comunidades_linguisticas WHERE id_comunidad_linguistica = 99) = 'No indica', 'comunidad lingüística 99 es "No indica"');
SELECT pg_temp.verificar((SELECT count(*) FROM pueblos) = 6, 'pueblos del INE: 6 filas');
SELECT pg_temp.verificar((SELECT string_agg(id_comunidad_linguistica::text, ',' ORDER BY id_comunidad_linguistica) FROM comunidades_linguisticas WHERE nombre_comunidad_linguistica IN ('K''iche''', 'Kaqchikel', 'Xinka', 'Garífuna', 'Castellano')) = '10,11,23,24,25', 'códigos oficiales del INE: K''iche'' 10, Kaqchikel 11, Xinka 23, Garífuna 24, Castellano 25');
SELECT pg_temp.verificar((SELECT count(*) FROM departamentos) = 22, 'departamentos: 22 filas');
SELECT pg_temp.verificar((SELECT count(*) FROM municipios) = 340, 'municipios: 340 filas');
SELECT pg_temp.verificar((SELECT count(*) FROM (SELECT id_departamento FROM municipios GROUP BY 1) x) = 22, 'los 340 municipios cubren los 22 departamentos');
SELECT pg_temp.verificar((SELECT nombre_municipio FROM municipios WHERE id_municipio = 108) = 'Mixco', 'municipio 108 es Mixco');
SELECT pg_temp.verificar((SELECT d.nombre_departamento FROM municipios m JOIN departamentos d USING (id_departamento) WHERE m.id_municipio = 108) = 'Guatemala', 'Mixco pertenece al departamento Guatemala');
SELECT pg_temp.verificar((SELECT count(*) FROM presentaciones) >= 4, 'presentaciones: al menos 4');
SELECT pg_temp.verificar((SELECT nombre_rol FROM roles WHERE id_area IS NULL) = 'administrador', 'solo el administrador no tiene área');
SELECT pg_temp.verificar((SELECT count(*) FROM roles WHERE id_area IS NOT NULL) = 6, 'los otros 6 roles tienen área');
SELECT pg_temp.verificar((SELECT count(DISTINCT estado) FROM atenciones) = 6, 'el seed de pruebas trae atenciones en los 6 estados');
SELECT pg_temp.verificar((SELECT count(*) FROM pacientes) >= 30, 'el seed de pruebas trae 30 pacientes o más');
SELECT pg_temp.verificar((SELECT count(*) FROM pacientes WHERE datos_incompletos) >= 2, 'hay emergencias con datos incompletos');
SELECT pg_temp.verificar((SELECT count(*) FROM usuarios WHERE nombre_usuario IN ('padmin','precepcion','psignos','pdoctor','pdoctora','pnutricion','pvacunacion','pfarmacia')) = 8, 'los 8 usuarios de prueba existen');
SELECT pg_temp.verificar((SELECT count(*) FROM usuarios WHERE contrasena_hash LIKE '$argon2id$%') = (SELECT count(*) FROM usuarios), 'todas las contraseñas están guardadas con argon2id');
SELECT pg_temp.verificar((SELECT count(*) FROM usuarios WHERE nombre_usuario !~ '^[a-z]+$') = 0, 'los nombres de usuario cumplen el formato');
SELECT pg_temp.verificar((SELECT rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls FROM pg_roles WHERE rolname = 'sjlc_app') = false, 'sjlc_app no tiene privilegios especiales');
SELECT pg_temp.verificar(current_setting('TimeZone') = 'America/Guatemala', 'zona horaria America/Guatemala');
SELECT pg_temp.verificar((SELECT count(*) FROM pg_extension WHERE extname IN ('unaccent','pg_trgm')) = 2, 'extensiones unaccent y pg_trgm instaladas');
SELECT pg_temp.verificar((SELECT count(*) FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE') >= 25, 'las 23 tablas del modelo más sesiones y migraciones_aplicadas existen (como mínimo)');
SELECT pg_temp.verificar((SELECT count(*) FROM information_schema.tables WHERE table_schema = 'public' AND table_name IN ('rutas_tipos_atencion','establecimientos')) = 0, 'las tablas descartadas (rutas_tipos_atencion y establecimientos) no existen');
SELECT pg_temp.cerrar();
